"use strict";
import { MouseoverTooltip, TooltipSize } from "components/Tooltip";
import { Flex, Separator, Text, styled as UiStyled } from "ui/src";
function formatLargeNumber(value) {
  if (!Number.isFinite(value)) {
    return "0.00";
  }
  if (value >= 1e9) {
    return `${(value / 1e9).toFixed(2)}B`;
  }
  if (value >= 1e6) {
    return `${(value / 1e6).toFixed(2)}M`;
  }
  if (value >= 1e3) {
    return `${(value / 1e3).toFixed(2)}K`;
  }
  return value.toFixed(2);
}
function formatVotingDeadline(timestamp) {
  if (!timestamp) {
    return "";
  }
  const date = new Date(timestamp * 1e3);
  return date.toString();
}
function getTimeRemainingText(days, hours, isLoading) {
  if (isLoading) {
    return "...";
  }
  if (days > 0) {
    return `ends in ${days} ${days === 1 ? "day" : "days"}`;
  }
  if (hours > 0) {
    return `ends in ${hours} ${hours === 1 ? "hour" : "hours"}`;
  }
  return "ending soon";
}
export default function VotingRound({ voteData }) {
  const {
    totals,
    timing,
    isLoading
  } = voteData;
  const TextTypeOne = UiStyled(Text, {
    variant: "body3",
    color: "$neutral2",
    fontSize: "$mdall"
  });
  const TextTypeTwo = UiStyled(TextTypeOne, {
    color: "$neutral3"
  });
  return <Flex
    row
    borderStyle="solid"
    flexDirection="column"
    borderWidth={1}
    borderColor="$surface2Hovered"
    borderRadius={"$rounded12"}
    p={"$spacing16"}
  >
      <Flex
    className="top"
    row
    $lg={{ flexDirection: "column" }}
    justifyContent="space-between"
    width={"100%"}
    gap={"$spacing16"}
  >
        <Flex className="left" gap={"$spacing8"} alignItems="flex-start">
          <Flex row gap={"$spacing8"} alignItems="center">
            <Text variant={"body3"}>Current voting round</Text>
            <MouseoverTooltip
    text={!isLoading && timing.votingDeadline ? formatVotingDeadline(timing.votingDeadline) : ""}
    size={TooltipSize.Max}
    placement="top"
    disabled={isLoading || !timing.votingDeadline}
  >
              <Text
    variant={"body3"}
    px={"$spacing16"}
    py={"$spacing6"}
    borderRadius={"$roundedFull"}
    backgroundColor={"$surface2"}
    color={"$neutral1"}
    textAlign="center"
    cursor="pointer"
    $lg={{ variant: "body4", px: "$spacing12", py: "$spacing4" }}
  >
                {getTimeRemainingText(timing.daysRemaining, timing.hoursRemaining, isLoading)}
              </Text>
            </MouseoverTooltip>
          </Flex>
        </Flex>

        <TextTypeTwo maxWidth={"30rem"} variant={"body3"} color={"$neutral3"}>
          Voters earn a share of transaction fees and incentives for helping govern how emissions are distributed.
        </TextTypeTwo>
      </Flex>

      <Separator my={"$spacing16"} width={"100%"} borderColor={"$surface2Hovered"} />

      <Flex
    className="bottom"
    row
    $lg={{ flexDirection: "column" }}
    justifyContent="space-between"
    width={"100%"}
    gap={"$spacing16"}
  >
        <Flex className="left" row gap={"$spacing8"}>
          <TextTypeTwo>Total voting power this epoch:</TextTypeTwo>
          <TextTypeOne>{isLoading ? "..." : formatLargeNumber(totals.totalVotingPower)}</TextTypeOne>
        </Flex>

        <Flex
    className="right"
    maxWidth={"30rem"}
    width={"100%"}
    flexWrap="wrap"
    row
    alignItems="center"
    gap={"$spacing8"}
  >
          {
    /* trading fees from last epoch */
  }
          <Flex row gap={"$spacing2"} centered>
            <TextTypeTwo>Trading fees (last epoch):</TextTypeTwo>
            <TextTypeOne>{isLoading ? "..." : formatLargeNumber(totals.totalTradingFees)}</TextTypeOne>
          </Flex>
          {
    /* Total Incentives: */
  }
          <Flex row gap={"$spacing2"} centered>
            <TextTypeTwo>Total incentives:</TextTypeTwo>
            <TextTypeOne>
              {isLoading ? "..." : formatLargeNumber(totals.totalIncentives)}
            </TextTypeOne>
          </Flex>
          {
    /*  */
  }
          <Flex row gap={"$spacing2"} centered>
            <TextTypeTwo>Total rewards:</TextTypeTwo>
            <TextTypeOne>
              {isLoading ? "..." : formatLargeNumber(totals.totalRewards)}
            </TextTypeOne>
          </Flex>
          {
    /*  */
  }
          <Flex row gap={"$spacing2"} centered>
            <TextTypeTwo>New emissions:</TextTypeTwo>
            <TextTypeOne>{isLoading ? "..." : formatLargeNumber(totals.newEmissions)}</TextTypeOne>
          </Flex>
        </Flex>
      </Flex>
    </Flex>;
}
