"use strict";
import { useAccount } from "hooks/useAccount";
import { useModalState } from "hooks/useModalState";
import { useVeABXUserLocks } from "hooks/useVeABXLocks";
import { VotingStatusUtils, useVotingStatus } from "hooks/useVotingStatus";
import { useAppDispatch, useAppSelector } from "state/hooks";
import { selectPendingVotes, selectSelectedLock } from "state/voting/slice";
import { Flex, Separator, StarBorderButton, Text, useIsDarkMode, useMedia, useSporeColors } from "ui/src";
import { ModalName } from "uniswap/src/features/telemetry/constants";
import { calculateTimeUntilUnlock } from "utils/lockCalculations";
import { formatEther } from "viem";
import styled from "styled-components";
import Slider from "./Slider";
const VoteBottomSlider = () => {
  const colors = useSporeColors();
  const media = useMedia();
  const dispatch = useAppDispatch();
  const selectedLock = useAppSelector(selectSelectedLock);
  const pendingVotes = useAppSelector(selectPendingVotes);
  const { toggleModal: toggleVotingModal } = useModalState(ModalName.Voting);
  const account = useAccount();
  const { data: userLocks } = useVeABXUserLocks(account.address);
  const locksCards = userLocks?.filter((lock) => {
    const isOwner = lock.owner.toLowerCase() === account.address?.toLowerCase();
    const isNotExpired = lock.permanent || !calculateTimeUntilUnlock(lock.lockEnd).expired;
    return isOwner && isNotExpired;
  }) || [];
  const { lockStatuses, isLoading: votingStatusLoading, isRefetching } = useVotingStatus(locksCards);
  const selectedLockStatus = lockStatuses.find((status) => status.tokenId === selectedLock?.id);
  const selectedLockHasVoted = selectedLockStatus?.hasVoted || false;
  const selectedLockAllocatedPercentage = selectedLockStatus?.allocatedPercentage || 0;
  const selectedLockRemainingPercentage = selectedLockStatus?.remainingPercentage || 100;
  const selectedLockIsFullyAllocated = selectedLockStatus?.isFullyAllocated || false;
  const totalPendingPercentage = pendingVotes.reduce((total, vote) => total + (vote.percentage || 0), 0);
  const canVote = selectedLock && pendingVotes.length > 0 && !selectedLockIsFullyAllocated;
  const isDarkMode = useIsDarkMode();
  const handleVote = () => {
    if (!selectedLock) {
      alert("Please select a veNFT lock from the carousel below first.");
      return;
    }
    if (selectedLockIsFullyAllocated) {
      alert(
        "This lock has already allocated 100% of its voting power. Select a different lock or wait until Thursday when voting resets."
      );
      return;
    }
    if (pendingVotes.length === 0) {
      alert('Please select at least one gauge to vote on by clicking "Select" next to the gauges above.');
      return;
    }
    toggleVotingModal();
  };
  const Button = styled.div`
    all: unset;
    padding: 8px 8px;
    background-color: ${colors.surface2.val};
    border-radius: 10px;
    border: 1px solid ${colors.surface3.val};
    transition: all 0.2s ease;
    cursor: pointer;
    display: flex;
    justify-content: center;
    align-items: center;
    &:hover {
      background-color: ${colors.surface2Hovered.val};
    }
  `;
  const votingStatusSummary = VotingStatusUtils.getVotingStatusSummary(lockStatuses);
  return <Flex
    $platform-web={{ position: "fixed", zIndex: 1e3 }}
    bottom={0}
    left={"50%"}
    transform={"translateX(-50%)"}
    hoverStyle={{ backgroundColor: isDarkMode ? "#2c2c2c" : "#e0e0e0" }}
    backdropFilter="blur(20px)"
    transition="all 0.2s ease-in-out"
    p={"$spacing8"}
    borderRadius={"$rounded16"}
    borderWidth={1}
    borderColor={"$surface3"}
    maxWidth={1100}
    width={"100%"}
    mx={"auto"}
    justifyContent="space-between"
    alignItems="center"
    $md={{ width: "calc(100% - 32px)", p: "$spacing12" }}
    position="relative"
  >
      <Flex
    position="absolute"
    borderRadius={"$rounded16"}
    inset={0}
    height={"100%"}
    width={"100%"}
    style={{
      background: isDarkMode ? `linear-gradient(180deg, ${colors.surface1.val} 0%, ${colors.surface1Hovered.val} 100%)` : `linear-gradient(180deg, ${colors.surface1.val} 0%, ${colors.surface1Hovered.val} 100%)`
    }}
  />
      <Flex width={"100%"}>
        {
    /* Vote Summary */
  }
        <Flex flexDirection="row" justifyContent="center" gap="$gap6" minWidth={200}>
          {selectedLock && pendingVotes.length > 0 ? <>
              <Text variant="body4" color="$neutral2">
                Lock #{selectedLock.id} • {pendingVotes.length} pool{pendingVotes.length !== 1 ? "s" : ""}
              </Text>
              <Separator height="100%" width={1} backgroundColor="$neutral3" vertical />
              <Text variant="body4" color="$statusSuccess">
                {formatEther(BigInt(selectedLock.votingPower)).slice(0, 8)} veABX ready
              </Text>
            </> : <>
              <Text variant="body4" color="$neutral2">
                {votingStatusSummary.unvoted} of {votingStatusSummary.total} locks available
              </Text>
              {votingStatusSummary.voted > 0 && <>
                  <Separator height="100%" width={1} backgroundColor="$neutral3" vertical />
                  <Text variant="body4" color="$cyanBase">
                    {votingStatusSummary.voted} already voted this epoch
                  </Text>
                </>}
            </>}
        </Flex>
        <Flex row gap={"$spacing16"} mt={"$spacing8"}>
          <Slider lockStatuses={lockStatuses} votingStatusSummary={votingStatusSummary} />
          <Flex row alignItems="center">
            <StarBorderButton
    onClick={canVote ? handleVote : void 0}
    speed="3s"
    disabled={!canVote}
    py={16}
    px={40}
    $md={{ py: 10, px: 20 }}
  >
              <Text variant={media.lg ? "buttonLabel3" : "buttonLabel2"} color="$neutral1">
                Vote
              </Text>
            </StarBorderButton>
          </Flex>
        </Flex>
      </Flex>
    </Flex>;
};
export default VoteBottomSlider;
